#include <Arduino.h>
#include <Adafruit_GFX.h>    
#include <Adafruit_ST7735.h> 
#include <SPI.h>
#include <Adafruit_GFX.h>
#include <Adafruit_ST7735_and_ST7789_Library.h>

// 配線はそのままでOK（D0~D3を避けた安全なピン）
#define TFT_RST    4   // 基板のD4
#define TFT_DC     5   // 基板のD5
#define TFT_CS     6   // 基板のD6

// 【重要】ピンの指定を「3つ」だけにします！
// これにより、XIAOの内蔵通信機能（ハードウェアSPI）が強制的に発動し、フリーズが解けます。
Adafruit_ST7735 tft = Adafruit_ST7735(TFT_CS, TFT_DC, TFT_RST);

void setup() {
  // Chromebookの通知連打を防ぐ命綱
  Serial.begin(115200);
  delay(2000); // 起動を確実に安定させるために少し長めに待ちます

  Serial.println("Starting LCD... Now!"); // 動き出した合図

  // 液晶の初期化
  tft.initR(INITR_GREENTAB); 

  // 画面を「青色」で塗りつぶす
  tft.fillScreen(ST7735_BLUE);

  // 文字の設定
  tft.setCursor(10, 50);          
  tft.setTextColor(ST7735_WHITE); 
  tft.setTextSize(2);             

  // 画面に文字を表示
  tft.println("Hello!");
}

void loop() {
  // 2秒おきにシリアルへ文字を送り、生きていることを証明します
  Serial.println("LCD is working perfectly!");
  delay(2000);
}
